 89→
 90→    function escapeHtml(str) {
 91→      var d = document.createElement('div');
 92→      d.textContent = str;
 93→      return d.innerHTML;
 94→    }
 95→
 96→    var cfg = { blockCheckoutInCart: false };
 97→    try {
 98→      var meta = META_RAW ? JSON.parse(META_RAW) : null;
 99→      if (meta) cfg = Object.assign(cfg, meta);
100→    } catch(e) {}
101→
102→    function init() {
103→      var wrapper = document.getElementById('zcc-cart-validator');
104→      if (!wrapper) return;
105→
106→      var isValid, zip, storedShop;
107→      try {
108→        isValid = sessionStorage.getItem('zcc:valid');
109→        zip = sessionStorage.getItem('zcc:zip');
110→        storedShop = sessionStorage.getItem('zcc:shop');
111→      } catch(e) { return; }
112→
113→      // Only act if the stored validation is for THIS shop
114→      if (!isValid || storedShop !== SHOP) return;
115→
116→      if (isValid === 'false' && zip) {
117→        // Show warning banner
118→        wrapper.style.display = 'block';
119→        wrapper.innerHTML = '<div class="zcc-cv-banner">'
120→          + '<span class="zcc-cv-icon">⚠️</span>'
121→          + '<div class="zcc-cv-content">'
122→          + '<p class="zcc-cv-title">Delivery Not Available for Your Area</p>'
123→          + '<p class="zcc-cv-msg">Your ZIP code <span class="zcc-cv-zip">' + escapeHtml(zip) + '</span> is outside our current delivery area. Please remove restricted items or check a different ZIP code.</p>'
124→          + '<div class="zcc-cv-actions">'
125→          + '<button class="zcc-cv-dismiss" onclick="document.getElementById(\'zcc-cart-validator\').style.display=\'none\'">Dismiss</button>'
126→          + '</div>'
127→          + '</div>'
128→          + '</div>';
129→
130→        // Optionally block checkout buttons
131→        if (cfg.blockCheckoutInCart) {
132→          var CHECKOUT_SELECTORS = [
133→            '[name="checkout"]',
134→            '.cart__checkout-button',
135→            '.cart-checkout-btn',
136→            'button[data-action="checkout"]',
137→            '.checkout-button',
138→            'input[name="checkout"]',
139→            '[href="/checkout"]',
140→            'a.btn[href*="checkout"]'
141→          ];
142→
143→          CHECKOUT_SELECTORS.forEach(function(sel) {
144→            try {
145→              document.querySelectorAll(sel).forEach(function(el) {
146→                el.classList.add('zcc-checkout-blocked');
147→                el.setAttribute('data-zcc-checkout-blocked', 'true');
148→                el.setAttribute('title', 'Delivery is not available for ZIP code ' + escapeHtml(zip) + '. Please update your ZIP code.');
149→              });
150→            } catch(e) {}
151→          });
152→
153→          // Add notice below checkout buttons
154→          var notice = document.createElement('p');
155→          notice.className = 'zcc-checkout-notice';
156→          notice.style.display = 'block';
157→          notice.textContent = 'Checkout unavailable — ZIP code ' + zip + ' is not in our delivery area.';
158→          wrapper.appendChild(notice);
159→        }
160→      }
161→    }
162→
163→    // Run on DOM ready
164→    if (document.readyState === 'loading') {
165→      document.addEventListener('DOMContentLoaded', init);
166→    } else {
167→      init();
168→    }
169→
170→    // Also listen for zcc:validated events (if widget and cart are on same page)
171→    window.addEventListener('zcc:validated', function(e) {
172→      try {
173→        var detail = e.detail;
174→        if (!detail.valid) {
175→          sessionStorage.setItem('zcc:valid', 'false');
176→          sessionStorage.setItem('zcc:zip', detail.zip);
177→        } else {
178→          sessionStorage.removeItem('zcc:valid');
179→          sessionStorage.removeItem('zcc:zip');
180→          var w = document.getElementById('zcc-cart-validator');
181→          if (w) w.style.display = 'none';
182→          // Re-enable checkout buttons if they were blocked
183→          document.querySelectorAll('[data-zcc-checkout-blocked="true"]').forEach(function(el) {
184→            el.classList.remove('zcc-checkout-blocked');
185→            el.removeAttribute('data-zcc-checkout-blocked');
186→            el.removeAttribute('title');
187→          });
188→        }
189→      } catch(e) {}
190→    });
191→  })();
192→  </script>
193→{% endif %}
